const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = $env.QDRANT_API_KEY || '';
const OLLAMA_URL = 'http://ollama:11434';

async function qdrantScroll(collection, filter, limit=100) {
  const body = {limit, with_payload: true, with_vector: false};
  if (filter) body.filter = filter;
  const d = await helpers.httpRequest({ method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify(body), url: `${QDRANT_URL}/collections/${collection}/points/scroll`, json: true });
  return d.result?.points || [];
}

async function qdrantStore(collection, id, vector, payload) {
  await helpers.httpRequest({ 
    method: 'PUT', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({points: [{id, vector, payload}]}), url: `${QDRANT_URL}/collections/${collection}/points` })
}

async function qdrantUpdate(collection, ids, payload) {
  await helpers.httpRequest({ method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({payload, points: ids}), url: `${QDRANT_URL}/collections/${collection}/points/payload` });
}

async function embed(text) {
  const d = await helpers.httpRequest({ method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({model: 'nomic-embed-text', input: text}), url: `${OLLAMA_URL}/api/embed`, json: true });
  return d.embeddings?.[0] || null;
}

function uuid() { return ((function(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){var r=Math.random()*16|0,v=c==='x'?r:(r&0x3|0x8);return v.toString(16);});})()); }

const trajectories = await qdrantScroll('trajectories', null, 100);
const now = Date.now();
const recent = trajectories.filter(t => {
  const created = new Date(t.payload?.created_at || 0).getTime();
  return (now - created) < 7 * 24 * 60 * 60 * 1000;
});

// Extract context -> memories_accessed patterns
const patterns = {};
for (const t of recent) {
  const context = t.payload?.trigger_context || t.payload?.task_type || 'unknown';
  const memoriesAccessed = t.payload?.memories_accessed || t.payload?.recalled_ids || [];
  if (!Array.isArray(memoriesAccessed) || memoriesAccessed.length === 0) continue;

  if (!patterns[context]) patterns[context] = {memories: {}, count: 0};
  patterns[context].count++;
  for (const mid of memoriesAccessed) {
    patterns[context].memories[mid] = (patterns[context].memories[mid] || 0) + 1;
  }
}

// Store patterns with frequency >= 2
let stored = 0;
for (const [context, data] of Object.entries(patterns)) {
  if (data.count < 2) continue;

  // Top 3 most accessed memories for this context
  const topMemories = Object.entries(data.memories)
    .sort((a,b) => b[1] - a[1])
    .slice(0, 3)
    .map(([id, freq]) => ({memory_id: id, frequency: freq}));

  const vec = await embed('predictive pattern: ' + context);
  if (vec) {
    await qdrantStore('predictive_patterns', uuid(), vec, {
      trigger_context: context, top_memories: topMemories,
      occurrence_count: data.count, updated_at: new Date().toISOString()
    });
    stored++;
  }
}

return [{json: {trajectories_analyzed: recent.length, patterns_found: Object.keys(patterns).length, stored}}];
